set -eu
cd "$HOME/agent-workspace/repos/photomap/worktrees/unified-ux-20261104-v1/frontend"
node --input-type=module <<'JS'
import { chromium, expect } from "@playwright/test";
const browser = await chromium.launch({
  headless: true,
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
});
try {
  for (const viewport of [{ width: 390, height: 844 }, { width: 1440, height: 900 }]) {
    const context = await browser.newContext({ viewport });
    const page = await context.newPage();
    const jsErrors = [];
    const assetErrors = [];
    page.on("pageerror", (error) => jsErrors.push(error.message));
    page.on("response", (response) => {
      if (response.url().startsWith("https://photomap.pl/") && response.status() >= 400) {
        assetErrors.push(`${response.status()} ${response.url()}`);
      }
    });
    await page.goto("https://photomap.pl/?release-smoke=09be8c4", { waitUntil: "domcontentloaded", timeout: 45000 });
    await expect(page.locator(".map-frame")).toBeVisible({ timeout: 25000 });
    await expect(page.getByTestId("pinned-media-drawer")).toHaveAttribute("data-stage", "collapsed", { timeout: 25000 });
    const tour = page.locator(".map-tour");
    if (await tour.isVisible()) {
      await tour.getByRole("button", { name: "Pomiń", exact: true }).click();
    }
    await page.getByRole("button", { name: "Filtry mapy" }).click();
    await expect(page.locator("#map-tools-panel")).toBeVisible();
    await expect(page.locator(".drawer-scrim--map-tools")).toHaveCSS("background-color", "rgba(0, 0, 0, 0)");
    await page.getByRole("button", { name: "Ustawienia widoku mapy" }).click();
    await expect(page.locator("#map-tools-panel")).toContainText("Miejsca na mapie");
    await page.getByRole("button", { name: "Ustawienia widoku mapy" }).click();
    const drawer = page.getByTestId("pinned-media-drawer");
    await drawer.getByRole("button", { name: "Rozwiń szufladę zdjęć" }).click();
    await expect(drawer).toHaveAttribute("data-stage", "collection");
    await drawer.getByRole("button", { name: "Zwiń szufladę zdjęć" }).click();
    await expect(drawer).toHaveAttribute("data-stage", "collapsed");
    await page.getByRole("button", { name: "Otwórz menu" }).click();
    await expect(page.locator("#app-side-drawer")).toHaveClass(/is-open/);
    await page.getByRole("button", { name: "Zamknij menu" }).click();
    await expect(page.locator("#app-side-drawer")).not.toHaveClass(/is-open/);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    if (overflow > 2) throw new Error(`Horizontal overflow: ${overflow}px`);
    if (jsErrors.length || assetErrors.length) {
      throw new Error(JSON.stringify({ viewport, jsErrors, assetErrors }));
    }
    console.log(JSON.stringify({ viewport, filters: "ok", view: "ok", drawer: "ok", menu: "ok", overflow, jsErrors: 0, assetErrors: 0 }));
    await context.close();
  }
} finally {
  await browser.close();
}
JS
echo LIVE_CHROME_UX_SMOKE_PASS
